	mux.HandleFunc("GET /products/{id}/reviews", handleListProductReviews).Methods("GET")
	mux.HandleFunc("POST /products/{id}/reviews", handleCreateReview).Methods("POST")
}

// handleListProductReviews returns paginated reviews for a product.
func handleListProductReviews(w http.ResponseWriter, r *http.Request) {
	id := r.PathValue("id")
	if id == "" {
		writeError(w, http.StatusNotFound, codeNotFound, "product ID is required")
		return
	}
	p, err := parsePage(r)
	if err != nil {
		writeError(w, http.StatusBadRequest, codeBadQuery, err.Error())
		return
	}
	items, info := paginate(s.reviewStore.ListByProduct(id), p)
	writeList(w, items, info)
}

// handleCreateReview creates a new review with validation.
func handleCreateReview(w http.ResponseWriter, r *http.Request) {
	var req createReviewRequest
	if err := decodeBody(r, &req); err != nil {
		writeError(w, http.StatusBadRequest, codeBadJSON, "request body must be valid JSON")
		return
	}
	if err := req.validate(); err != nil {
		writeError(w, http.StatusUnprocessableEntity, codeValidationFailed, err.Error())
		return
	}
	if _, exists := s.reviewStore.Get(req.UserID); !exists {
		writeError(w, http.StatusUnprocessableEntity, codeValidationFailed, "user_id: unknown user")
		return
	}
	review := req.Review
	st.reviewStore.Create(review)
	writeJSON(w, http.StatusCreated, review)
}

// createReviewRequest defines the validation rules for the review body.
type createReviewRequest struct {
	Review   Review   `json:"review"`
	UserID   string   `json:"user_id"`
	Rating   int      `json:"rating"`
	Body     string   `json:"body"`
}

func (req createReviewRequest) validate() error {
	if req.UserID == "" {
		return validationError{"user_id", "is required"}
	}
	if req.Rating < 1 || req.Rating > 5 {
		return validationError{"rating", "must be between 1 and 5"}
	}
	if len(req.Body) > 500 {
		return validationError{"body", "must be at most 500 characters"}
	}
	return nil
}

