	writeError(w, http.StatusNotFound, codeNotFound, fmt.Sprintf("%s %s not found", kind, id))
}

func writeRaw(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
