	defer st.mu.RUnlock()
	rv, ok := st.items[id]
	return rv, ok
}

// ListByProduct returns the product's reviews sorted by ID.
func (st *ReviewStore) ListByProduct(productID string) []Review {
	st.mu.RLock()
	defer st.mu.RUnlock()
	out := []Review{}
	for _, rv := range st.items {
		if rv.ProductID == productID {
